import { APISchemaBase, type Attribute, type Prim, type Stage } from 'typescript-usd/usd'

/**
 * UsdShadeConnectableAPI is an API schema that provides a common
 * interface for creating outputs and making connections between shading 
 * parameters and outputs. The interface is common to all UsdShade schemas
 * that support Inputs and Outputs, which currently includes UsdShadeShader,
 * UsdShadeNodeGraph, and UsdShadeMaterial .
 *
 * One can construct a UsdShadeConnectableAPI directly from a UsdPrim, or
 * from objects of any of the schema classes listed above.  If it seems
 * onerous to need to construct a secondary schema object to interact with
 * Inputs and Outputs, keep in mind that any function whose purpose is either
 * to walk material/shader networks via their connections, or to create such
 * networks, can typically be written entirely in terms of 
 * UsdShadeConnectableAPI objects, without needing to care what the underlying
 * prim type is.
 *
 * Additionally, the most common UsdShadeConnectableAPI behaviors
 * (creating Inputs and Outputs, and making connections) are wrapped as
 * convenience methods on the prim schema classes (creation) and 
 * UsdShadeInput and UsdShadeOutput.
 */
export class ConnectableAPI extends APISchemaBase {
  static readonly typeName: string = "ConnectableAPI"

  static get(stage: Stage, path: string): ConnectableAPI {
    return new ConnectableAPI(stage.getPrim(path), stage)
  }

  static getSchemaAttributeNames(includeInherited = true): string[] {
    const names = includeInherited
      ? []
      : []
    return names
  }

  // --(BEGIN CUSTOM CODE)--
  // UsdShadeConnectableAPI::_IsCompatible (connectableAPIBehavior.cpp:
  // 842-851): the API is valid only on prims with a registered behavior.
  isValid(): boolean {
    return super.isValid() && getConnectableAPIBehavior(this._prim) !== null
  }

  // UsdShadeConnectableAPI::HasConnectableAPI (connectableAPIBehavior.cpp:
  // 880-885).
  static hasConnectableAPI(schemaType: TfType): boolean {
    return hasConnectableAPIBehaviorForType(schemaType)
  }

  // UsdShadeConnectableAPI::IsContainer / RequiresEncapsulation.
  isContainer(): boolean {
    return getConnectableAPIBehavior(this._prim)?.isContainer() ?? false
  }
  requiresEncapsulation(): boolean {
    return getConnectableAPIBehavior(this._prim)?.requiresEncapsulation() ?? false
  }

  createInput(name: string, typeName: string): ShadeInput {
    this._declareAttr(`inputs:${name}`, typeName)
    return new ShadeInput(this._prim, name)
  }

  createOutput(name: string, typeName = 'token'): ShadeOutput {
    this._declareAttr(`outputs:${name}`, typeName)
    return new ShadeOutput(this._prim, name)
  }

  getInput(name: string): ShadeInput { return new ShadeInput(this._prim, name) }
  getOutput(name: string): ShadeOutput { return new ShadeOutput(this._prim, name) }

  // UsdShadeConnectableAPI::GetInputs / GetOutputs (connectableAPI.cpp:
  // 507-527, 549-569): the attributes in the namespace, authored only or
  // including un-authored built-ins.
  getInputs(onlyAuthored = true): ShadeInput[] {
    return attributeNamesInNamespace(this._prim, 'inputs:', onlyAuthored)
      .map(name => new ShadeInput(this._prim, name))
  }
  getOutputs(onlyAuthored = true): ShadeOutput[] {
    return attributeNamesInNamespace(this._prim, 'outputs:', onlyAuthored)
      .map(name => new ShadeOutput(this._prim, name))
  }
}


function attributeNamesInNamespace(prim: Prim, namespace: string, onlyAuthored: boolean): string[] {
  if (onlyAuthored) return authoredAttributeNamesInNamespace(prim, namespace)
  return prim.getPropertyNames(name => name.startsWith(namespace))
    .filter(name => prim.getAttr(name)?.isValid())
    .map(name => name.slice(namespace.length))
}

// ---- Read-side helpers ----

// UsdShadeConnectableAPI::GetInputs / GetOutputs with onlyAuthored
// (connectableAPI.cpp:507-569): the authored attributes in the namespace,
// in UsdPrim::GetAuthoredPropertiesInNamespace order (dictionary order,
// then propertyOrder; prim.cpp:1413-1441).
function authoredAttributeNamesInNamespace(prim: Prim, namespace: string): string[] {
  return prim.getAuthoredPropertyNames(name => name.startsWith(namespace))
    .filter(name => prim.getAttr(name)?.isValid())
    .map(name => name.slice(namespace.length))
}

export function getInputNames(prim: Prim): string[] {
  return authoredAttributeNamesInNamespace(prim, 'inputs:')
}

export function getOutputNames(prim: Prim): string[] {
  return authoredAttributeNamesInNamespace(prim, 'outputs:')
}

// Follows a property's connection chain through NodeGraph boundaries until
// it reaches a property with no further connection (the effective source).
// Mirrors UsdShade's "compute attribute source" resolution: a NodeGraph
// output connected to an inner shader output, or a shader input connected
// to an outer NodeGraph interface input, are both pass-throughs.
export function computeEffectiveSource(stage: Stage, propertyPath: string, maxDepth = 32): ConnectionSource | null {
  let current = propertyPath
  let last: ConnectionSource | null = null

  for (let i = 0; i < maxDepth; i++) {
    const attr = stage.get(current)
    const connections = attr?.getConnections() ?? []
    if (connections.length === 0) return last
    const source = parseSourcePath(connections[0]!)
    if (!source) return last
    last = source
    current = connections[0]!
  }
  return last
}

// OpenUSD v26.11.1 utils.cpp:126-232: follow container interfaces, stop at
// non-container outputs, reject non-container input sources, and use an
// authored local value only when no connected producer was found.
export function getValueProducingAttributes(
  stage: Stage,
  propertyPath: string,
  shaderOutputsOnly = false,
): Attribute[] {
  const visit = (path: string, active: ReadonlySet<string>): Attribute[] => {
    if (active.has(path)) return []
    const spec = stage.get(path)
    if (!spec || !parseSourcePath(path)) return []
    const next = new Set(active).add(path)
    const result: Attribute[] = []
    for (const connection of spec.getConnections()) {
      const source = parseSourcePath(connection)
      if (!source || !stage.get(connection)) continue
      if (isContainer(stage, source.primPath)) {
        result.push(...visit(connection, next))
      } else if (source.sourceType === 'output') {
        // Shader outputs are terminals even if they themselves have authored
        // connections. CanConnect remains a separate advisory validation API.
        result.push(stage._primHandle(source.primPath).attr(`outputs:${source.name}`))
      }
    }
    if (!result.length && !shaderOutputsOnly && spec.hasAuthoredValue()) {
      result.push(stage._primHandle(spec.primPath).attr(spec.name))
    }
    return result
  }
  return visit(propertyPath, new Set())
}

// UsdShadeConnectableAPI — inputs, outputs, and connections.
// Reference: pxr/usd/usdShade/connectableAPI.h, input.h, output.h
//
// Inputs live in the `inputs:` namespace, outputs in `outputs:`.
// A connection is the attr's connectionPaths field pointing at a property
// path like '/Mat/Tex.outputs:rgb'.

import type { Type as TfType } from 'typescript-usd/tf'
import { getConnectableAPIBehavior, hasConnectableAPIBehaviorForType } from './connectableAPIBehavior.ts'

export type SourceType = 'input' | 'output'

export interface ConnectionSource {
  primPath: string
  name: string          // bare name without the inputs:/outputs: prefix
  sourceType: SourceType
}

// Result of a CanConnect check: whether the connection is allowed and, when
// not, a human-readable reason (mirrors the `std::string *reason` out-param
// of UsdShadeConnectableAPIBehavior::CanConnect*).
export interface CanConnectResult {
  canConnect: boolean
  reason?: string
}

// UsdShadeConnectableAPI::IsContainer (connectableAPIBehavior.cpp:887-895):
// the registered behavior's answer, false when the prim has none.
export function isContainer(stage: Stage, primPath: string): boolean {
  const prim = stage.getPrim(primPath)
  return prim ? (getConnectableAPIBehavior(prim)?.isContainer() ?? false) : false
}

// UsdShadeConnectableAPI::RequiresEncapsulation
// (connectableAPIBehavior.cpp:897-905): false when the prim has no behavior.
export function requiresEncapsulation(stage: Stage, primPath: string): boolean {
  const prim = stage.getPrim(primPath)
  return prim ? (getConnectableAPIBehavior(prim)?.requiresEncapsulation() ?? false) : false
}

// The input's connectability metadata, defaulting to 'full' when unauthored
// (UsdShadeInput::GetConnectability). 'interfaceOnly' restricts an input to
// be driven only by another interfaceOnly input.
export function getConnectability(stage: Stage, inputPath: string): string {
  const v = stage.get(inputPath)?.getField('connectability')
  return typeof v === 'string' && v.length > 0 ? v : 'full'
}

// Parse a property path like '/Mat/Tex.outputs:rgb' into a ConnectionSource.
export function parseSourcePath(path: string): ConnectionSource | null {
  const dot = path.lastIndexOf('.')
  if (dot <= 0) return null
  const primPath = path.slice(0, dot)
  const prop = path.slice(dot + 1)
  if (prop.startsWith('outputs:')) return { primPath, name: prop.slice('outputs:'.length), sourceType: 'output' }
  if (prop.startsWith('inputs:')) return { primPath, name: prop.slice('inputs:'.length), sourceType: 'input' }
  return { primPath, name: prop, sourceType: 'output' }
}

// Reconstruct the full property path for a connection source.
function sourceFullPath(src: ConnectionSource): string {
  const prefix = src.sourceType === 'input' ? 'inputs:' : 'outputs:'
  return `${src.primPath}.${prefix}${src.name}`
}

// UsdShadeConnectionSourceInfo (OpenUSD 26.11.1 connectableAPI.h:737-815):
// the source of a connection as a connectable prim, the source attribute's
// base name, whether it is an input or an output, and an optional value
// type name used when the source attribute has to be created.
export class ConnectionSourceInfo {
  constructor(
    readonly source: ConnectableAPI,
    readonly sourceName: string,
    readonly sourceType: SourceType | 'invalid',
    readonly typeName = '',
  ) {}

  // connectableAPI.h:787-796: typeName is optional and not checked; the
  // source prim need only be valid, not connectable.
  isValid(): boolean {
    return this.sourceType !== 'invalid' && this.sourceName !== '' &&
      (this.source.prim?.isValid() ?? false)
  }

  // connectableAPI.h:800-805: typeName is not compared.
  equals(other: ConnectionSourceInfo): boolean {
    return this.sourceName === other.sourceName &&
      this.sourceType === other.sourceType &&
      this.source.path === other.source.path
  }
}

// UsdShadeUtils::GetConnectedSourcePath (utils.cpp:39-53): the source
// attribute's path for a valid source info, else the empty path.
export function getConnectedSourcePath(srcInfo: ConnectionSourceInfo): string {
  if (!srcInfo.isValid() || srcInfo.sourceType === 'invalid') return ''
  const prefix = srcInfo.sourceType === 'input' ? 'inputs:' : 'outputs:'
  return `${srcInfo.source.prim.path}.${prefix}${srcInfo.sourceName}`
}

// Normalize a connectToSource/canConnect argument (a handle, a source info
// or a raw property path string) into a ConnectionSource.
function resolveSource(source: ShadeOutput | ShadeInput | ConnectionSourceInfo | string): ConnectionSource | null {
  if (typeof source === 'string') return parseSourcePath(source)
  if (source instanceof ConnectionSourceInfo) {
    if (!source.isValid() || source.sourceType === 'invalid') return null
    return { primPath: source.source.path, name: source.sourceName, sourceType: source.sourceType }
  }
  return parseSourcePath(source.fullPath)
}

// The value type name a source info asks its created source attribute to
// have (_GetOrCreateSourceAttr, connectableAPI.cpp:109-138).
function sourceTypeName(source: ShadeOutput | ShadeInput | ConnectionSourceInfo | string): string {
  if (source instanceof ConnectionSourceInfo) return source.typeName
  if (typeof source === 'string') return ''
  return source.attr.isValid() ? source.attr.typeName : ''
}

// UsdShadeConnectableAPI::GetConnectedSources (connectableAPI.cpp:304-360):
// the valid sources of a shading attribute's connections, and the
// connection paths that do not name an existing inputs:/outputs: attribute.
function getConnectedSourcesOf(stage: Stage, attr: Attribute): [ConnectionSourceInfo[], string[]] {
  const sourceInfos: ConnectionSourceInfo[] = []
  const invalidSourcePaths: string[] = []
  for (const sourcePath of attr.isValid() ? attr.getConnections() : []) {
    const dot = sourcePath.lastIndexOf('.')
    const sourcePrim = dot > 0 ? stage.getPrim(sourcePath.slice(0, dot)) : undefined
    const sourceAttrName = sourcePath.slice(dot + 1)
    const sourceAttr = sourcePrim?.getAttr(sourceAttrName)
    if (!sourcePrim || !sourceAttr?.isValid() || sourceAttr.isRelationship) {
      invalidSourcePaths.push(sourcePath)
      continue
    }
    // UsdShadeUtils::GetBaseNameAndType: a legal inputs:/outputs: prefix.
    const sourceType: SourceType | null = sourceAttrName.startsWith('inputs:') ? 'input'
      : sourceAttrName.startsWith('outputs:') ? 'output' : null
    if (!sourceType) {
      invalidSourcePaths.push(sourcePath)
      continue
    }
    const sourceName = sourceAttrName.slice(sourceType === 'input' ? 'inputs:'.length : 'outputs:'.length)
    sourceInfos.push(new ConnectionSourceInfo(
      new ConnectableAPI(sourcePrim), sourceName, sourceType, sourceAttr.typeName))
  }
  return [sourceInfos, invalidSourcePaths]
}

// ---- CanConnect (UsdShadeConnectableAPI::CanConnect) ----
//
// connectableAPIBehavior.cpp:853-885: the registered behavior of the prim
// owning the input or output decides; a prim without one cannot connect.

export function canConnectInputToSource(
  stage: Stage, inputPath: string, source: ConnectionSource,
): CanConnectResult {
  const parsedInput = parseSourcePath(inputPath)
  if (!parsedInput) return { canConnect: false, reason: `Invalid input: ${inputPath}` }
  const prim = stage.getPrim(parsedInput.primPath)
  const behavior = prim ? getConnectableAPIBehavior(prim) : null
  if (!behavior) {
    return { canConnect: false, reason: `Prim '${parsedInput.primPath}' owning the input is not connectable.` }
  }
  return behavior.canConnectInputToSource(stage, inputPath, source)
}

export function canConnectOutputToSource(
  stage: Stage, outputPath: string, source: ConnectionSource,
): CanConnectResult {
  const parsedOutput = parseSourcePath(outputPath)
  if (!parsedOutput) return { canConnect: false, reason: `Invalid output: ${outputPath}` }
  const prim = stage.getPrim(parsedOutput.primPath)
  const behavior = prim ? getConnectableAPIBehavior(prim) : null
  if (!behavior) {
    return { canConnect: false, reason: `Prim '${parsedOutput.primPath}' owning the output is not connectable.` }
  }
  return behavior.canConnectOutputToSource(stage, outputPath, source)
}

// Dispatch a CanConnect query against a shading property path
// (UsdShadeConnectableAPI::CanConnect): inputs go through
// canConnectInputToSource, outputs through canConnectOutputToSource.
export function canConnect(
  stage: Stage, shadingPropPath: string, source: ConnectionSource,
): CanConnectResult {
  const parsed = parseSourcePath(shadingPropPath)
  if (!parsed) return { canConnect: false, reason: `Invalid shading property: ${shadingPropPath}` }
  return parsed.sourceType === 'input'
    ? canConnectInputToSource(stage, shadingPropPath, source)
    : canConnectOutputToSource(stage, shadingPropPath, source)
}

// True when the strongest opinion authoring a connection on `shadingAttrPath`
// was introduced through a specialize arc — i.e. the connection comes from a
// live base material. Mirrors
// UsdShadeConnectableAPI::IsSourceConnectionFromBaseMaterial.
export function isSourceConnectionFromBaseMaterial(stage: Stage, shadingAttrPath: string): boolean {
  return stage.isStrongestConnectionFromSpecializes(shadingAttrPath)
}

// OpenUSD v26.11.1 connectableAPI.cpp:109-178 (_GetOrCreateSourceAttr).
function authorConnection(stage: Stage, attr: Attribute, source: ConnectionSource, typeName = ''): boolean {
  const prim = stage.getPrim(source.primPath)
  if (!prim || !source.name) return false
  const sourceName = `${source.sourceType === 'input' ? 'inputs' : 'outputs'}:${source.name}`
  // If the source attribute doesn't exist, create it with the source info's
  // type name, falling back to the shading attribute's.
  if (!prim.getAttr(sourceName)?.isValid()) {
    stage.declareProperty(source.primPath, sourceName, typeName || attr.typeName)
  }
  attr.setConnections([sourceFullPath(source)])
  return true
}

// ---- Input / Output handles (authoring) ----

export class ShadeInput {
  constructor(
    private readonly _prim: Prim,
    readonly name: string,   // bare name, attr is inputs:NAME
  ) {}

  get attrName(): string { return `inputs:${this.name}` }
  get fullPath(): string { return `${this._prim.path}.${this.attrName}` }
  get attr(): Attribute { return this._prim.attr(this.attrName) }

  set(value: unknown): void { this.attr.set(value) }
  get(): unknown { return this.attr.get() }

  // UsdShadeInput::GetAttr / GetPrim / GetBaseName / GetTypeName
  // (input.h; input.cpp:49-96).
  getAttr(): Attribute { return this.attr }
  getPrim(): Prim { return this._prim }
  getBaseName(): string { return this.name }
  getTypeName(): string { return this.attr.typeName }
  getFullName(): string { return this.attrName }

  // UsdShadeInput::SetRenderType / GetRenderType / HasRenderType
  // (input.cpp:97-115): the renderType attribute metadata.
  setRenderType(renderType: string): boolean { return this.attr.setMetadata('renderType', renderType) }
  getRenderType(): string {
    const value = this.attr.getMetadata('renderType')
    return typeof value === 'string' ? value : ''
  }
  hasRenderType(): boolean { return this.attr.hasMetadata('renderType') }

  // UsdShadeInput::SetDocumentation / GetDocumentation / SetDisplayGroup /
  // GetDisplayGroup (input.cpp:201-239), through UsdObject's documentation
  // and displayGroup metadata.
  setDocumentation(docs: string): boolean {
    return this.attr.isValid() ? this.attr.setMetadata('documentation', docs) : false
  }
  getDocumentation(): string {
    const value = this.attr.isValid() ? this.attr.getMetadata('documentation') : undefined
    return typeof value === 'string' ? value : ''
  }
  setDisplayGroup(displayGroup: string): boolean {
    return this.attr.isValid() ? this.attr.setDisplayGroup(displayGroup) : false
  }
  getDisplayGroup(): string {
    const value = this.attr.isValid() ? this.attr.getMetadata('displayGroup') : undefined
    return typeof value === 'string' ? value : ''
  }

  // Sets the input's connectability metadata ('full' | 'interfaceOnly')
  // (UsdShadeInput::SetConnectability).
  setConnectability(connectability: string): void {
    this._prim.getStage().setPropertyField(this.fullPath, 'connectability', connectability)
  }

  // The input's connectability, defaulting to 'full'
  // (UsdShadeInput::GetConnectability).
  getConnectability(): string {
    return getConnectability(this._prim.getStage(), this.fullPath)
  }

  // UsdShadeInput::GetSdrMetadata / GetSdrMetadataByKey (input.cpp:118-139):
  // the sdrMetadata dictionary entries, stringified.
  getSdrMetadata(): Record<string, string> {
    const dict = this.attr.getMetadata('sdrMetadata')
    const result: Record<string, string> = {}
    if (dict && typeof dict === 'object') {
      for (const [key, value] of Object.entries(dict as Record<string, unknown>)) result[key] = String(value)
    }
    return result
  }

  // UsdShadeInput::SetSdrMetadata / SetSdrMetadataByKey (input.cpp:141-155):
  // UsdObject::SetMetadataByDictKey on the attribute, which sets the key in
  // the sdrMetadata dictionary of the spec at the edit target.
  setSdrMetadata(sdrMetadata: Record<string, string>): void {
    for (const [key, value] of Object.entries(sdrMetadata)) this.setSdrMetadataByKey(key, value)
  }
  setSdrMetadataByKey(key: string, value: string): void {
    const editTarget = this._prim.getStage().getEditTarget()
    const existing = editTarget.getLayer()?.getField(editTarget.mapToSpecPath(this.fullPath), 'sdrMetadata')
    const dict: Record<string, unknown> = existing && typeof existing === 'object'
      ? { ...(existing as Record<string, unknown>) } : {}
    dict[key] = value
    this.attr.setMetadata('sdrMetadata', dict)
  }
  // UsdShadeInput::HasSdrMetadataByKey (input.cpp:163-167).
  hasSdrMetadataByKey(key: string): boolean {
    const dict = this.attr.getMetadata('sdrMetadata')
    return !!dict && typeof dict === 'object' && key in (dict as Record<string, unknown>)
  }

  getSdrMetadataByKey(key: string): string {
    let value: unknown = this.attr.getMetadata('sdrMetadata')
    for (const component of key.split(':').filter(Boolean)) {
      if (!value || typeof value !== 'object') return ''
      value = (value as Record<string, unknown>)[component]
    }
    return value === undefined || value === null ? '' : String(value)
  }

  // Whether this input may be connected to the given source — mirrors
  // UsdShadeConnectableAPI::CanConnect.
  canConnect(source: ShadeOutput | ShadeInput | string): CanConnectResult {
    const src = resolveSource(source)
    if (!src) return { canConnect: false, reason: 'Invalid source.' }
    return canConnectInputToSource(this._prim.getStage(), this.fullPath, src)
  }

  // OpenUSD v26.11.1 connectableAPI.cpp:140-178: author valid source
  // information independently of the advisory CanConnect encapsulation check.
  connectToSource(source: ShadeOutput | ShadeInput | ConnectionSourceInfo | string): boolean {
    const src = resolveSource(source)
    if (!src) return false
    if (!authorConnection(this._prim.getStage(), this.attr, src, sourceTypeName(source))) return false
    return true
  }

  // UsdShadeConnectableAPI::DisconnectSource (connectableAPI.cpp:470-480):
  // remove the connection to sourceAttr, or with none, author an explicit
  // empty connection list that blocks weaker connections.
  disconnectSource(sourceAttr?: Attribute): boolean {
    if (sourceAttr) return this.attr.removeConnection(sourceAttr.getPath())
    this.attr.setConnections([])
    return true
  }

  // UsdShadeConnectableAPI::ClearSources (connectableAPI.cpp:482-486):
  // clear the connection opinion at the edit target.
  clearSources(): boolean { return this.attr.clearConnections() }
  clearSource(): boolean { return this.clearSources() }

  // UsdShadeInput::GetConnectedSources (input.cpp:303-308): the valid
  // sources and the invalid source paths, as Python's (sources, invalid).
  getConnectedSources(): [ConnectionSourceInfo[], string[]] {
    return getConnectedSourcesOf(this._prim.getStage(), this.attr)
  }

  getConnectedSource(): ConnectionSource | null {
    const paths = this.attr.getConnections()
    return paths.length > 0 ? parseSourcePath(paths[0]!) : null
  }

  // UsdShadeConnectableAPI::HasConnectedSource (connectableAPI.cpp:388-395):
  // whether any connection names a valid source.
  hasConnectedSource(): boolean {
    return this.getConnectedSources()[0].length > 0
  }

  getValueProducingAttributes(shaderOutputsOnly = false): Attribute[] {
    return getValueProducingAttributes(
      this._prim.getStage(), this.fullPath, shaderOutputsOnly)
  }
}

export class ShadeOutput {
  constructor(
    private readonly _prim: Prim,
    readonly name: string,   // bare name, attr is outputs:NAME
  ) {}

  get attrName(): string { return `outputs:${this.name}` }
  get fullPath(): string { return `${this._prim.path}.${this.attrName}` }
  get attr(): Attribute { return this._prim.attr(this.attrName) }

  // Whether this output may be connected to the given source.
  canConnect(source: ShadeOutput | ShadeInput | string): CanConnectResult {
    const src = resolveSource(source)
    if (!src) return { canConnect: false, reason: 'Invalid source.' }
    return canConnectOutputToSource(this._prim.getStage(), this.fullPath, src)
  }

  // OpenUSD v26.11.1 connectableAPI.cpp:140-178: CanConnect is advisory.
  connectToSource(source: ShadeOutput | ShadeInput | ConnectionSourceInfo | string): boolean {
    const src = resolveSource(source)
    if (!src) return false
    if (!authorConnection(this._prim.getStage(), this.attr, src, sourceTypeName(source))) return false
    return true
  }

  // UsdShadeOutput::GetAttr / GetPrim / GetBaseName / GetTypeName (output.h).
  getAttr(): Attribute { return this.attr }
  getPrim(): Prim { return this._prim }
  getBaseName(): string { return this.name }
  getTypeName(): string { return this.attr.typeName }
  getFullName(): string { return this.attrName }

  // UsdShadeOutput::DisconnectSource / ClearSources / GetConnectedSources /
  // HasConnectedSource (output.cpp), through the UsdShadeConnectableAPI
  // statics (connectableAPI.cpp:304-395, 470-486).
  disconnectSource(sourceAttr?: Attribute): boolean {
    if (sourceAttr) return this.attr.removeConnection(sourceAttr.getPath())
    this.attr.setConnections([])
    return true
  }
  clearSources(): boolean { return this.attr.clearConnections() }
  getConnectedSources(): [ConnectionSourceInfo[], string[]] {
    return getConnectedSourcesOf(this._prim.getStage(), this.attr)
  }
  hasConnectedSource(): boolean { return this.getConnectedSources()[0].length > 0 }

  getConnectedSource(): ConnectionSource | null {
    const paths = this.attr.getConnections()
    return paths.length > 0 ? parseSourcePath(paths[0]!) : null
  }

  getValueProducingAttributes(shaderOutputsOnly = false): Attribute[] {
    return getValueProducingAttributes(
      this._prim.getStage(), this.fullPath, shaderOutputsOnly)
  }
}

// ---- Connectable base for Shader / NodeGraph / Material ----
